// parseSparkplugTopic parses a Sparkplug topic and extracts metadata
func parseSparkplugTopic(topic string) map[string]string {
	// Use the actual TopicParser from the plugin for consistency
	parser := sparkplug_plugin.NewTopicParser()
	parsedTopic, err := parser.Parse(topic)
	if err != nil {
		return make(map[string]string)
	}

	metadata := make(map[string]string)
	metadata["group_id"] = parsedTopic.GroupID
	metadata["sparkplug_msg_type"] = parsedTopic.MessageType
	metadata["message_type"] = parsedTopic.MessageType
	metadata["edge_node_id"] = parsedTopic.EdgeNodeID

	if parsedTopic.DeviceID != "" {
		metadata["device_id"] = parsedTopic.DeviceID
	}

	return metadata
}
```

